-- Zhuyin prefix completion, ordered by common-character frequency.
--
-- Rime's built-in enable_completion orders candidates by remaining code
-- length, not by frequency: for `1` (ㄅ) every two-key code would come
-- before the more common three-key ones, so 不 would not be first.
--
-- zhuyin_completion_data.lua is generated by tools/make_zhuyin.py from the
-- puffzhuyin dictionary (terra_pinyin + essay.txt).  Each prefix maps to
-- its characters sorted by weight.  Characters that have the exact code are
-- excluded: the table translator already provides them, so exact candidates
-- stay first in table order.
--
-- Candidate quality 0 is below the table translator's weight (>= 1), so the
-- menu order is: exact code -> frequency-ordered completions.

local index = require("zhuyin_completion_data")
local bopomofo = require("zhuyin_bopomofo")

local function translator(input, seg, env)
  if not seg:has_tag("zhuyin") then
    return
  end
  local chars = index[input]
  if not chars or chars == "" then
    return
  end

  -- The table translator's preedit_format only runs when it has an exact
  -- match; for an incomplete code this translator is the one that keeps the
  -- segment alive, so it must set the Bopomofo preedit itself.
  local preedit = bopomofo.to_bopomofo(input)

  for text, _code in chars:gmatch("([^\t]+)\t([^\n]+)\n") do
    local cand = Candidate("zhuyin_completion", seg.start, seg._end, text, "")
    cand.preedit = preedit
    cand.quality = 0
    yield(cand)
  end
end

return translator
